const norm = $('Input Normalizer').item.json;
const rawInput = $input.item.json;
const content = rawInput?.choices?.[0]?.message?.content || '';
const reasoning = rawInput?.choices?.[0]?.message?.reasoning_content || '';
const rawText = content.trim() || reasoning.trim();

let devData = null;

try {
  const cleaned = rawText
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/```json/gi, '')
    .replace(/```/gi, '')
    .trim();

  const match = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
  if (match) {
    devData = JSON.parse(match[0]);
  }
} catch(e) {
  devData = null;
}

// Resilient Fallback Regex Parser if model produced unparseable output
if (!devData || (devData.isNull && devData.amount === undefined)) {
  const query = norm.query || '';
  const amtMatch = query.match(/(?:rs\.?|inr|rupees|\$)?\s*(\d+(?:\.\d{1,2})?)/i) || query.match(/(\d+(?:\.\d{1,2})?)\s*(?:rs\.?|inr|rupees)?/i);
  if (amtMatch) {
    const amt = parseFloat(amtMatch[1]);
    let item = query
      .replace(/(?:bought|spent|paid|for|of|on|a|an|the|rs\.?|inr|rupees|\$|\d+(?:\.\d+)?)/gi, ' ')
      .trim()
      .replace(/\s+/g, ' ');
    devData = {
      isNull: false,
      amount: amt,
      type: 'debit',
      targetParty: item || 'Unknown',
      category: 'Shopping'
    };
  }
}

if (!devData) {
  devData = { isNull: true, amount: 0, targetParty: 'Unknown' };
}

// 1. Support multi-item transactions array
if (devData.transactions && Array.isArray(devData.transactions) && devData.transactions.length > 0) {
  return devData.transactions.map(tx => {
    const amt = parseFloat(tx.amount) || 0;
    return {
      json: {
        ...norm,
        isNull: false,
        hasMissingData: amt === 0,
        missingFields: amt === 0 ? 'Amount' : '',
        amount: amt,
        category: tx.category || 'Shopping',
        vendor: tx.targetParty || tx.vendor || 'Unknown',
        type: (tx.type || 'debit').toLowerCase() === 'credit' ? 'Income' : 'Expense',
        medium: tx.medium || 'other',
        description: tx.description || '',
        date: tx.date_of_transaction || new Date().toISOString().split('T')[0]
      }
    };
  });
}

// 2. Single transaction flow
const amount = parseFloat(devData.amount) || 0;
const confidence = (devData.confidence || 'HIGH').toUpperCase();
let missingFields = Array.isArray(devData.missing) ? [...devData.missing] : [];

if (confidence === 'LOW') {
  devData.isNull = true;
} else if (confidence === 'MEDIUM' && missingFields.length === 0) {
  missingFields.push('Confirmation needed');
}

if (amount === 0 && !devData.isNull) missingFields.push('Amount');
if (!devData.targetParty && !devData.isNull) missingFields.push('Merchant');

const isTransactionNull = devData.isNull === true || (amount === 0 && !devData.targetParty);

return [{
  json: {
    ...norm,
    isNull: isTransactionNull,
    hasMissingData: missingFields.length > 0 && !isTransactionNull,
    missingFields: missingFields.join(', '),
    amount,
    category: devData.category || 'Other',
    vendor: devData.targetParty || 'Unknown',
    type: (devData.type || 'debit').toLowerCase() === 'credit' ? 'Income' : 'Expense',
    medium: devData.medium || 'other',
    description: devData.description || '',
    date: devData.date_of_transaction || new Date().toISOString().split('T')[0]
  }
}];

const pastTransactions = $input.all();

// Safely retrieve current transaction regardless of node renaming
let currentTx = {};
const candidateNodes = ['Clean & Format1', 'Clean & Format', 'Clean & Format2', 'Is Data Missing?', 'Is Transaction?'];
for (const name of candidateNodes) {
  try {
    const nodeObj = $(name);
    const item = (nodeObj && nodeObj.item && nodeObj.item.json) ? nodeObj.item.json : (nodeObj && nodeObj.first ? nodeObj.first().json : null);
    if (item && (item.amount !== undefined || item.query !== undefined)) {
      currentTx = item;
      break;
    }
  } catch(e) {}
}

let isDuplicate = false;
let duplicateReason = '';

if (pastTransactions.length > 0 && pastTransactions[0].json && pastTransactions[0].json.amount !== undefined) {
  const txDate = new Date(currentTx.date || new Date().toISOString().split('T')[0]);
  isDuplicate = pastTransactions.some(pt => {
    if (!pt.json || pt.json.amount === undefined) return false;
    const diffDays = Math.abs((txDate - new Date(pt.json.date)) / (1000 * 60 * 60 * 24));
    const sameAmount = parseFloat(pt.json.amount) === parseFloat(currentTx.amount);
    const v1 = (pt.json.vendor || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const v2 = (currentTx.vendor || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const isFuzzyVendor = (v1.includes(v2) && v2.length > 3) || (v2.includes(v1) && v1.length > 3);
    if (sameAmount && diffDays <= 1 && isFuzzyVendor) {
      duplicateReason = `Matches past transaction: Rs.${pt.json.amount} at ${pt.json.vendor}`;
      return true;
    }
    return false;
  });
}

return { json: { ...currentTx, isDuplicate, duplicateReason } };
